class Word {
    std::string& _name;  // Reference member: Must be initialized in the constructor's member initialization list. The compiler treats this as a pointer internally, requiring binding to an existing object.
    const int _cnt;     // Const member: Must be initialized to a constant value and cannot be modified afterward. The compiler ensures initialization in the constructor body or list.
public:
    // Synthesized default constructor (if not user-defined):
    Word() : _name(*new std::string("default")) , _cnt(0) {}  // Example of how the compiler might synthesize it, though in practice, it would error if _name isn't properly bound.
    // User-defined constructor for clarity:
    Word(std::string& name, int cnt) : _name(name), _cnt(cnt) {}  // Implementation note: The compiler generates code to bind _name to the provided reference and initialize _cnt, involving pointer assignments and memory stores.
};

