#include <string>
#include <iostream>

// Advanced C++ Object Model example demonstrating compiler-synthesized constructors
class Word {
    std::string& _name;  // Reference to a string, requires initialization
    const int _cnt;      // Const integer, requires initialization
public:
    // If no constructor is provided, the compiler attempts to synthesize one,
    // but this will fail at compile-time for references without a binding.
    Word(std::string& name, int cnt) : _name(name), _cnt(cnt) {}
    void display() const {
        std::cout << _name << " count: " << _cnt << std::endl;  // Usage example
    }
};

int main() {
    std::string externalName = "Example";
    Word obj(externalName, 42);  // Invokes user-defined constructor
    obj.display();  // Outputs: Example count: 42
    return 0;
}
